import{z as i,x as s,o as e,c as p,q as r,j as n,D as E,d as B,s as l,S as o,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"数据质量体系","description":"","frontmatter":{"title":"数据质量体系","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/alt-data-quality.md","filePath":"quant/alt-data-quality.md","lastUpdated":1791413859000}'),d={name:"quant/alt-data-quality.md"};function C(D,a,u,F,m,c){const A=s("Mermaid");return e(),p("div",null,[a[2]||(a[2]=r('<h1 id="数据质量体系" tabindex="-1">数据质量体系 <a class="header-anchor" href="#数据质量体系" aria-label="Permalink to &quot;数据质量体系&quot;">​</a></h1><div class="epigraph"><p>数据质量不是一份描述文档，是一组带阈值的验收测试；没有阈值的质量维度只是形容词。</p><footer>—— 据 Croushore and Stark, Journal of Econometrics, 2001；数据质量维度框架的一般实践整理</footer></div><p><a href="/quant/alt-crawler-compliance">上一课</a>把自采管道立成带许可注册表与原始归档的工程件；归档回答「当时是什么」，本课回答「现在这份好不好」。主干课立了偏差谱系：<a href="/quant/alt-data-backfill-bias">回填偏差</a>的四层前视、<a href="/quant/alt-panel-construction">面板构造</a>的映射、日历与缺失三张表。本课把偏差防治落成<strong>体系</strong>：维度、阈值、门禁、事故——让「数据坏了」从 IC 缓慢死亡变成一次可拦截的事故。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>另类数据的失败模式与行情数据不同：它很少报错。覆盖悄悄缩（面板用户流失，某类商户整体消失）；口径悄悄换（供应商改算法、改样本，序列连续而含义已断）；交付悄悄迟（延迟分布的尾从两天拖到九天，信号可用日整体后移）；单位悄悄错（元与千元、毛与净）。四件事都无异常日志，唯一的外显是 IC 逐年衰减——等你从收益上发现，回测与实盘的差异已经不可归因：是信号失效，还是进料变质？缺口因此不是「更多质量检查」，而是<strong>挂在决策上的阈值与拦截机制</strong>。</p><p><span class="marginnote">p95、p99 是「分位数」：把延迟从小到大排队，p95 就是排在 95% 位置的那个值——它刻画「最慢的那 5% 有多慢」，比平均值更接近实盘体感。平均值 2 天、p99 却 9 天的面板，意味着大约每百次交付就有一次信号当天根本没到。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>六个维度，各配阈值。覆盖：宇宙与时间的单元格矩阵，核心段覆盖不得低于基线的 \\(95\\%\\)，骤降即事故。及时：交付延迟的分布，对 \\(p95\\) 与 \\(p99\\) 设上限，上限由信号的持有期反推——日频信号的延迟预算与月频不同。有效：模式、类型与值域规则，硬失败直接拦截，不进特征管道。一致：跨源对账，自采样本与供应商对同一实体的值比对，容差带预先声明。准确：对官方基准的 nowcast 误差控制在声明的区间。唯一：主键与去重。三个机制把维度变成体系：门禁挂在管道上——不合格数据不进特征，这是<a href="/quant/feature-store-research">特征商店三原则</a>的执行层；周度 vintage 快照与 IC 重放——每周对同一历史窗口重算一次，终版与各 vintage 的 IC 差就是回填贡献的可测值，回填课的判据由此变成例行作业；事故与复盘——跌破阈值即事故，归档走<a href="/quant/research-postmortem">研究复盘</a>模板，死因必须落在判据上。</p><p><span class="marginnote">95% 看着宽松，换个角度算：若宇宙有 2000 只股票，5% 的缺口就是 100 只。若缺的恰是某个行业或市值段，当日截面在该段直接失明——所以阈值要配「分块检查」：总量达标而某一层塌了，同样算事故。</span></p>',9)),(e(),n(o,null,{default:E(()=>[l(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E6%96%B0%E4%B8%80%E6%89%B9%E6%95%B0%E6%8D%AE%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20G1%7B%22%E8%A6%86%E7%9B%96%E4%B8%8E%E5%8F%8A%E6%97%B6%E8%BE%BE%E6%A0%87%EF%BC%9F%22%7D%0A%20%20G1%20--%3E%7C%E5%90%A6%7C%20INC%5B%22%E4%BA%8B%E6%95%85%EF%BC%9A%E6%8B%A6%E6%88%AA%E5%B9%B6%E5%BD%92%E6%A1%A3%22%5D%0A%20%20G1%20--%3E%7C%E6%98%AF%7C%20G2%7B%22%E6%9C%89%E6%95%88%E3%80%81%E4%B8%80%E8%87%B4%E3%80%81%E5%94%AF%E4%B8%80%E9%80%9A%E8%BF%87%EF%BC%9F%22%7D%0A%20%20G2%20--%3E%7C%E5%90%A6%7C%20INC%0A%20%20G2%20--%3E%7C%E6%98%AF%7C%20FEAT%5B%22%E8%BF%9B%E5%85%A5%E7%89%B9%E5%BE%81%E7%AE%A1%E9%81%93%22%5D%0A%20%20SNAP%5B%22%E5%91%A8%E5%BA%A6%20vintage%20%E5%BF%AB%E7%85%A7%22%5D%20--%3E%20RP%5B%22IC%20%E9%87%8D%E6%94%BE%EF%BC%9A%E7%BB%88%E7%89%88%E5%AF%B9%E6%AF%94%E5%90%84%20vintage%22%5D%0A%20%20RP%20--%3E%20AL%7B%22IC%20%E5%B7%AE%E8%B6%85%E5%B8%A6%EF%BC%9F%22%7D%0A%20%20AL%20--%3E%7C%E6%98%AF%7C%20INC%0A%20%20AL%20--%3E%7C%E5%90%A6%7C%20OK%5B%22%E8%AE%B0%E5%85%A5%E8%B4%A8%E9%87%8F%E5%8F%B0%E8%B4%A6%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[B("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"阈值为什么必须挂在决策上：质量维度只有在「这个信号多快地用它」面前才有数值答案，脱离持有期谈延迟上限、脱离宇宙谈覆盖率，都只能得到形容词。NA 不是零，覆盖阈值决定当日截面谁进场，这是面板课立过的规矩；门禁把它从规矩变成开关。不这么做的错法：质量做成月度报表——报表出来时，带病数据已经上线三周，IC 的三周衰减永久记在信号头上；或者只监控特征分布不监控原始进料——供应商改了样本，特征分布的变化被误读为市场状态变化。",-1)),a[5]||(a[5]=t("p",null,"四种静默失败与各自的拦截阈值——回答「数据没报错时，靠什么发现它坏了」：",-1)),(e(),n(o,null,{default:E(()=>[l(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20F1%5B%22%E8%A6%86%E7%9B%96%E6%82%84%E6%82%84%E7%BC%A9%22%5D%20--%3E%20D1%5B%22%E8%A6%86%E7%9B%96%E7%9F%A9%E9%98%B5%EF%BC%9A%E6%A0%B8%E5%BF%83%E6%AE%B5%E4%BD%8E%E4%BA%8E%E5%9F%BA%E7%BA%BF%2095%25%20%E5%8D%B3%E4%BA%8B%E6%95%85%22%5D%0A%20%20F2%5B%22%E5%8F%A3%E5%BE%84%E6%82%84%E6%82%84%E6%8D%A2%22%5D%20--%3E%20D2%5B%22%E8%B7%A8%E6%BA%90%E5%AF%B9%E8%B4%A6%20%2B%20vintage%20IC%20%E9%87%8D%E6%94%BE%22%5D%0A%20%20F3%5B%22%E4%BA%A4%E4%BB%98%E6%82%84%E6%82%84%E8%BF%9F%22%5D%20--%3E%20D3%5B%22%E5%BB%B6%E8%BF%9F%E5%88%86%E5%B8%83%20p95%2Fp99%20%E4%B8%8A%E9%99%90%22%5D%0A%20%20F4%5B%22%E5%8D%95%E4%BD%8D%E6%82%84%E6%82%84%E9%94%99%22%5D%20--%3E%20D4%5B%22%E6%A8%A1%E5%BC%8F%E4%B8%8E%E5%80%BC%E5%9F%9F%E8%A7%84%E5%88%99%EF%BC%9A%E7%A1%AC%E5%A4%B1%E8%B4%A5%E6%8B%A6%E6%88%AA%22%5D%0A%20%20D1%20--%3E%20X%5B%22%E9%97%A8%E7%A6%81%EF%BC%9A%E4%B8%8D%E8%BF%9B%E7%89%B9%E5%BE%81%E7%AE%A1%E9%81%93%22%5D%0A%20%20D2%20--%3E%20X%0A%20%20D3%20--%3E%20X%0A%20%20D4%20--%3E%20X%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">对账样本要分层抽：按实体规模、地区与时间分层各抽若干，容差带按层声明。总量对账通过而某层对不上，是最常见的「总体看着没事」陷阱——供应商收缩的恰恰是那一个小层。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课测的是「数据像不像它应该有的样子」，不测「信息还在不在」——后者是信号衰减，归本课程后面「从数据到策略」一课的退场机制管辖。行情与基本面数据的质量由数据工程主干处理，另类数据只是同一思想在脏进料上的特化。供应商的合同义务与赔付条款是采购问题，归成本结构课；跨源对账的容差带设定依赖用途，本课不给通用数值，只给「预先声明」这条纪律。</p><p><span class="marginnote">初学者容易把「IC 下降」一律归咎数据变质。判别线索在归因表：进料各阈值若全绿、vintage IC 差也在带内，掉的就是信号（衰减或拥挤），不是数据——两者处方完全不同：前者修管道或换供应商，后者降仓或退场。先把病因分对，再动手。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>六维度各配阈值：覆盖、及时、有效、一致、准确、唯一，脱离用途的阈值只是形容词。</li><li>门禁挂在管道上，不合格进不了特征；月度报表不是质量体系。</li><li>周度 vintage 快照加 IC 重放，把回填偏差从论文判据变成 cron 作业。</li><li>跌破阈值即事故，复盘死因落在判据上，负结果可检索。</li><li>出处：Croushore and Stark, <em>Journal of Econometrics</em>, 2001；本课程回填偏差、面板构造、特征商店各课的数据质量条款。</li></ul>',6))])}const _=i(d,[["render",C]]);export{f as __pageData,_ as default};
